+        "INSERT INTO rectangles (record_id, x, y, w, h, sort, color)"
+        " VALUES (?, ?, ?, ?, ?, ?, ?)"));
     for (int i = 0; i < rectangles.size(); ++i) {
         const Rect &rect = rectangles.at(i);
         insert.addBindValue(recordId);
